"""Bounded real-child capture for public sanity checks, independent of candidate Python I/O."""
import os,pathlib,selectors,signal,stat,subprocess,time

def scratch_over_budget(path):
    stack=[pathlib.Path(path)];size=count=0
    while stack:
        p=stack.pop()
        try:
            s=p.lstat();count+=1
            if stat.S_ISREG(s.st_mode):size+=max(s.st_size,s.st_blocks*512)
            elif stat.S_ISDIR(s.st_mode):
                with os.scandir(p) as entries:stack.extend(pathlib.Path(x.path) for x in entries)
        except FileNotFoundError:continue
        if size>1024**3 or count>50000:return True
    return False

def child(argv,raw=b'',timeout=180):
    if os.geteuid()==0:raise RuntimeError('public checks require nonroot execution')
    proc=None;streams=[];selector=selectors.DefaultSelector();old={};signals={signal.SIGINT,signal.SIGTERM}
    def interrupted(sig,frame):
        for s in signals:signal.signal(s,signal.SIG_IGN)
        raise KeyboardInterrupt('public check interrupted')
    for s in signals:old[s]=signal.signal(s,interrupted)
    try:
        signal.pthread_sigmask(signal.SIG_BLOCK,signals)
        try:
            proc=subprocess.Popen(argv,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,close_fds=True,
                env={'PATH':'/opt/java/bin:/usr/local/bin:/usr/bin:/bin','HOME':'/workspace','LANG':'C','LC_ALL':'C','TMPDIR':'/workspace/tmp','PYTHONHASHSEED':'0','PYTHONUNBUFFERED':'1','PYTHONDONTWRITEBYTECODE':'1','OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'})
        finally:signal.pthread_sigmask(signal.SIG_UNBLOCK,signals)
        streams=[proc.stdin,proc.stdout,proc.stderr];captured=[bytearray(),bytearray()];offset=0
        for s in streams:os.set_blocking(s.fileno(),False)
        if raw:selector.register(proc.stdin,selectors.EVENT_WRITE,-1)
        else:proc.stdin.close()
        selector.register(proc.stdout,selectors.EVENT_READ,0);selector.register(proc.stderr,selectors.EVENT_READ,1)
        start=time.monotonic();storage=start
        while selector.get_map():
            now=time.monotonic()
            if now-start>=timeout:raise ValueError('child wall limit exceeded')
            if now>=storage:
                if scratch_over_budget('/workspace/tmp'):raise RuntimeError('scratch emergency brake: infrastructure error/no score')
                storage=now+.25
            for key,_ in selector.select(min(.1,timeout-(now-start))):
                stream,index=key.fileobj,key.data
                if index==-1:
                    try:n=os.write(stream.fileno(),raw[offset:offset+65536])
                    except BlockingIOError:continue
                    except BrokenPipeError:n=0;offset=len(raw)
                    offset+=n
                    if offset==len(raw):selector.unregister(stream);stream.close()
                else:
                    cap=(64*1024**2,1024**2)[index]
                    try:block=os.read(stream.fileno(),min(65536,cap-len(captured[index])+1))
                    except BlockingIOError:continue
                    if not block:selector.unregister(stream);stream.close()
                    elif len(block)+len(captured[index])>cap:raise ValueError('child output limit exceeded')
                    else:captured[index].extend(block)
        code=proc.wait(timeout=max(.001,timeout-(time.monotonic()-start)))
        return code,bytes(captured[0]),bytes(captured[1])
    finally:
        for s in signals:signal.signal(s,signal.SIG_IGN)
        try:
            if proc is not None:
                if proc.poll() is None:
                    proc.terminate()
                    try:proc.wait(timeout=5)
                    except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=5)
            selector.close()
            for s in streams:s.close()
        finally:
            for s,handler in old.items():signal.signal(s,handler)
